    "statement": "Na antiga União Soviética, o jornal do Partido Comunista, o Pravda, cuja tradução quer dizer “verdade”, não titubeou: defendeu o autoritarismo como a única história viável. Até mesmo países de reconhecida tradição liberal costumam patinar quando precisam lembrar de um passado que preferem esquecer. Esse é o caso do regime de Vichy na França (1940–1944), quando as elites locais colaboraram com o nazismo, ou mesmo da Espanha, que até hoje não consegue acertar suas contas com o período violento da Guerra Civil (1936–1939), que dividiu, e ainda divide, sua população. Mas são os governos de raiz autoritária que costumam ser os mais “afiados” na hora de acionar esse tipo de expediente político. O nazismo de Adolf Hitler (1933–1945) inventou um passado “ariano” para os alemães: puro e não corrompido pelos demais imigrantes e pessoas consideradas degeneradas.\n\n(Lilia Schwarcz. www.nexojornal.com.br, 08.04.2019. Adaptado.)\n\nA discussão contida no excerto evidencia que as narrativas históricas podem ser utilizadas para",
