    "statement": "A entrega do feudo ao vassalo era feita em uma cerimônia, dividida em três atos: homenagem, juramento de fidelidade e investidura. Na homenagem, o vassalo, colocando suas mãos entre as mãos de seu senhor, fazia uma declaração de vontade. Quanto ao juramento de fidelidade, era prestado pelo vassalo com a mão sobre o Evangelho. Já a investidura, aspecto material do contrato, consistia na concessão do feudo através da entrega de um elemento que o simbolizava, como um punhado de terra ou um ramo de árvore.\n\n(Maria de Nazareth Corrêa Accioli Lobato. “Relações feudo-vassálicas na Inglaterra do século XII: uma perspectiva literária”. Brathair, 2014. Adaptado.)\n\nA cerimônia descrita no excerto, dividida em três atos, tinha como principal finalidade",
