    "statement": "A obsolescência programada, também conhecida como obsolescência planejada, é um fenômeno utilizado por alguns fabricantes para fazer com que determinados produtos tenham uma vida útil menor. O produto vem de fábrica com sua data de validade já curta, programado para quebrar depois de alguns anos (ou meses), ou simplesmente dar defeito em alguma peça que não é possível trocar. Dessa forma, um produto que poderia durar anos acaba indo para o lixo em pouco tempo. Segundo uma pesquisa feita pela agência ambiental do governo alemão, cresceu o número de eletrodomésticos que precisam ser trocados depois de apenas 5 anos de uso. Em 2004, a porcentagem de eletrodomésticos que tinham essa baixa durabilidade era de 3,5% e foi para 8,13% em 2018.\n\n(https://ecoassist.com.br, 26.10.2021. Adaptado.)\n\nAlém da produção de lixo eletrônico, uma consequência ambiental da obsolescência programada é",
