    "statement": "Para responder às questões de 01 a 05, leia o soneto do poeta parnasiano Raimundo Correia.\n\nNo circo\n\nAbria o circo a arena iluminada\nDo povo às grossas vagas¹ tumultuosas;\nFervia tudo em pompa; a variada\nCor das vestes, as rendas preciosas,\n\nO verde, o azul, as sedas, os lavores²\nDos luzentes metais da cor do dia;\nMas nesta febre múltipla de cores,\nSomente a cor vermelha não se via;\n\nEm aplausos a turba se desata,\nSurge em pleno espetáculo o acrobata,\nPula, e na corda bamba se ajoelha;\n\nArqueia o corpo; a corda estala e ringe³;\nEle cai, parte o crânio, e o solo tinge\nA cor que não se via, a cor vermelha.\n\n(Raimundo Correia. Poesia completa e prosa, 1961.)\n\n1vaga: conjunto de pessoas em movimento. 2 lavor: ornamento. 3 ringir: ranger.\n\nEstá empregada em sentido figurado a palavra sublinhada no seguinte verso:",
