    "statement": "Presume-se que tenham sido trazidos forçadamente para o Brasil cerca de 40% dos africanos vitimados pela escravidão moderna. Foram eles e seus descendentes que constituí ram a quase total força de trabalho existente durante os mais de trezentos anos em que vigorou a instituição escravocrata brasileira. Assim, a escravidão acabou por penetrar todos os aspectos da sociedade brasileira durante esse período. Tão intensa quanto a própria escravidão foram os tipos de resistência apresentados pelos sujeitos escravizados ao sistema que lhes fora imposto. A resistência revelou-se desde a recusa vã em deixar suas terras, famílias, culturas e histórias na África, passando pela rebelião durante a insalubre travessia do Atlântico, até as formas mais radicais, como assassinato de seus escravizadores, nos locais de trabalho forçado.\n\n(Maria Jorge dos Santos Leite. “Tráfico atlântico, escravidão e resistência no Brasil”. Sankofa. Revista de História da África e\n\nde Estudos da Diáspora Africana, 2017. Adaptado.)\n\nSegundo o excerto, a experiência da diáspora africana no Brasil foi marcada pela",
