    "statement": "O Panamá foi, por muito tempo, uma província da Colômbia. Sua independência se tornou realidade em novembro de 1903, graças ao interesse estadunidense pelo projeto de um canal ligando o Atlântico ao Pacífico. O governo dos Estados Unidos não conseguia chegar a um acordo satisfatório com as autoridades colombianas. O presidente americano Theodore Roosevelt decidiu resolver o impasse apoiando as pretensões de independência dos habitantes da região, que retribuíram o favor rapidamente com um novo acordo, bastante generoso. “É quase 100% certo, tão certo quanto possível ao analisar os documentos históricos, que, se os Estados Unidos não tivessem tomado esta decisão, o Panamá ainda hoje faria parte da Colômbia”, declarou o pesquisador Noel Maurer, que escreveu um livro sobre a história do Canal do Panamá.\n\n(Arturo Wallace. www.bbc.com, 03.01.2025. Adaptado.)\n\nA atuação dos Estados Unidos no Panamá, descrita no excerto, constitui um exemplo de",
