    "statement": "As medidas dos catetos de um triângulo retângulo ABC são iguais a 4 cm e 6 cm, conforme mostra a figura, com h representando a medida da altura AH relativamente ao lado BC.\n\nUsando a aproximação 13 ≈ 3,6, a altura h, em cm, vale:",
