    "statement": "Em uma competição entre alunos para o lançamento de foguetes construídos com garrafas PET, foi proposta uma construção representada no esquema da figura.\n\n(http://static.even3.com)\n\nNessa proposta de foguete, o propulsor deveria ter a pressão gerada por uma reação química entre o ácido acético (CH₃COOH) contido no vinagre e o bicarbonato de sódio (NaHCO₃). O alcance do foguete depende, entre outros fatores, da pressão gerada pela produção do dióxido de carbono, conforme a reação a seguir.\n\nCH₃COOH (aq) + NaHCO₃ (s) → CH₃COONa (aq) + CO₂ (g) + H₂O (ℓ)\n\nConsiderando que a massa de bicarbonato de sódio e o volume de vinagre utilizados pelos competidores sejam os mesmos, o foguete que atingirá mais rapidamente a pressão interna necessária para o lançamento será o construído pelo competidor que utilizar",
