    "number": "Questão 01",
    "subject": "Português",
    "detail": "Português — UEA 2026 Acompanhamento III",
    "difficulty": "Difícil",
    "statement": "Para responder às questões de 01 a 03, leia o início do texto “Teia de aranha não é cabelo nem macarrão”, do biólogo brasileiro Fernando Reinach.\n\nVocê já deve ter visto uma aranha pendurada em um único fio de sua teia. Deve ter observado como ela é capaz de aumentar rapidamente o comprimento do fio. Em poucos segundos, uma aranha pode produzir mais de dez centímetros de fio. Imagine se nosso cabelo crescesse com essa velocidade. Teríamos que nos barbear três vezes por dia.\n\nA diferença entre o processo de fabricação do fio de cabelo e do fio de seda das aranhas explica a diferença de velocidade do crescimento. No caso do cabelo, as células presentes no bulbo capilar (o que chamamos de raiz) sintetizam as proteínas que constituem o fio e, à medida que essas proteínas ficam prontas, são adicionadas à ponta do fio localizada dentro do bulbo capilar, aumentando seu comprimento. O crescimento é lento e constante. No caso do fio de seda das aranhas, uma glândula produz as proteínas que vão constituir o fio, e essas proteínas são estocadas em um pequeno saco. Quando a aranha quer sintetizar um pedaço de fio, as proteínas são ejetadas do saco através de tubos muito finos, formando os fios.\n\nO mecanismo é semelhante a uma máquina de fazer macarrão — que, ao fazer a massa passar por um orifício, forma os fios. O problema é que, no caso do macarrão, podemos esperar algumas horas para a massa secar e o macarrão endurecer. No caso das aranhas, no momento em que o fio é ejetado, ele já tem que estar pronto para suportar o peso do animal. Isso significa que o processo de solidificação precisa ser rápido. A novidade é que foi descoberto o truque usado pelas aranhas para produzir rapidamente uma grande quantidade de fio.\n\n(Folha de lótus, escorregador de mosquito, 2018.)\n\nO texto do biólogo Fernando Reinach é um artigo de divulgação científica. Uma característica textual que o afasta de um artigo científico acadêmico é o emprego de linguagem",
