    "statement": "Com o fim da Primeira Guerra Mundial, impôs-se à Alemanha uma paz punitiva, justificada pelo argumento de que o Estado era o único responsável pela guerra e por todas as suas consequências (a cláusula da “culpa de guerra”), para mantê-la permanentemente enfraquecida. Isso foi conseguido não tanto por perdas territoriais; essa paz punitiva foi, na realidade, assegurada privando-se a Alemanha de uma marinha e uma força aérea efetivas; limitando-se seu exército a 100 mil homens; impondo-se “reparações” (pagamentos dos custos da guerra incorridos pelos vitoriosos) teoricamente infinitas; pela ocupação militar de parte da Alemanha Ocidental; e, não menos, privando-se a Alemanha de todas as suas antigas colônias no ultramar. Com exceção das cláusulas territoriais, nada restava do Tratado de Versalhes em meados da década de 1930.\n\n(Eric Hobsbawm. Era dos extremos: o breve século XX:\n\n1914-1991, 1995. Adaptado.)\n\nO cenário descrito no excerto contribuiu para",
