    "statement": "Leia um trecho do manifesto de fundação da Ação Integralista Brasileira (AIB), publicado em 1932 por Plínio Salgado, e um excerto sobre a relação desse movimento com o nazismo.\n\nTexto 1\n\nO cosmopolitismo, isto é, a influência estrangeira, é um mal de morte para o nosso Nacionalismo. Combatê-lo é o nosso dever. [...] Os nossos lares estão impregnados de estrangeirismos; as nossas palestras, o nosso modo de encarar a vida, não são mais brasileiros. Os brasileiros das cidades não conhecem os pensadores, os escritores, os poetas nacionais.\n\n(https://integralismo.org.br)\n\nTexto 2\n\nA relação do movimento integralista com os nazistas não era novidade. Havia uma aproximação entre os dois grupos, que possuíam muitas relações e algumas semelhanças. Plínio Salgado enxergou no nazismo uma solução capaz de alcançar o poder no Brasil, desenvolvendo de forma discreta uma relação de apoio ao regime nazista.\n\n(Adriana Ribeiro. www.politize.com.br, 03.04.2023. Adaptado.)\n\nSobre o movimento integralista, os excertos demonstram",
